challenge.solution:
const launch = document.querySelector("#launch");
const status = document.querySelector("#status");

function updateLaunch() {
  // read data-fuel, turn it into a number, update the button and #status
  const fuel = Number(launch.getAttribute("data-fuel"));
  if (fuel >= 50) {
    launch.removeAttribute("disabled");
    status.textContent = `Ready for launch (fuel ${fuel})`;
  } else {
    launch.setAttribute("disabled", "");
    status.textContent = `Not enough fuel (fuel ${fuel})`;
  }
}

updateLaunch();

// change the href attribute of the #docs link
document.querySelector("#docs").setAttribute("href", "https://developer.mozilla.org");

